import{_ as t,a as i,b as r}from"./chunks/4ceb50ff1ca80ab5f262.Jzb2XgBc.js";import{_ as a}from"./chunks/ac945418977052fbacd6.CObdY42w.js";import{_ as o,C as n,o as s,c as m,j as e,a as u,E as h,a5 as d}from"./chunks/framework.DNkHA0lr.js";const q=JSON.parse('{"title":"用你的大脑赚取百万（将你的知识转化为一家企业）","description":"","frontmatter":{"title":"用你的大脑赚取百万（将你的知识转化为一家企业）","originalTitle":"Make Millions With Your Mind (Turn Your Knowledge Into A Business)","date":"2023-11-17","originalUrl":"https://thedankoe.com/letters/make-millions-with-your-mind-turn-your-knowledge-into-a-business/","minutes":20,"sourceHash":"08bf7cb57752ffba1f2e5b5c118923da1022543908c297a2057165c5185ccec2","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/make-millions-with-your-mind-turn-your-knowledge-into-a-business/"}]]},"headers":[],"relativePath":"letters/make-millions-with-your-mind-turn-your-knowledge-into-a-business.md","filePath":"letters/make-millions-with-your-mind-turn-your-knowledge-into-a-business.md"}'),c={name:"letters/make-millions-with-your-mind-turn-your-knowledge-into-a-business.md"};function g(b,p,f,k,_,y){const l=n("ArticleMeta");return s(),m("div",null,[p[0]||(p[0]=e("h1",{id:"用你的大脑赚取百万-将你的知识转化为一家企业",tabindex:"-1"},[u("用你的大脑赚取百万（将你的知识转化为一家企业） "),e("a",{class:"header-anchor",href:"#用你的大脑赚取百万-将你的知识转化为一家企业","aria-label":'Permalink to "用你的大脑赚取百万（将你的知识转化为一家企业）"'},"​")],-1)),h(l),p[1]||(p[1]=d('<p><a href="https://www.youtube.com/embed/2DTZ6Kcdtmk?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>在我年轻的时候，我做出了一个至关重要的观察。</p><p>我必须靠我的大脑去赚钱，而不是靠我的时间。</p><p>我把体力劳动者和创意工作者区分开来。</p><p>体力劳动者会试图在特定的时间范围内，完成他们身体所能承受的尽可能多的工作。</p><p>创意工作者则会专注于解决那些能带来最大成果的问题，无论花费多少时间。</p><p>体力劳动者被锁定在固定的薪水和日程表中，他们的努力只能换来一定数量的报酬。</p><p>创意工作者创造他们自己的薪水和日程表，根据他们解决问题的水平来获取报酬。</p><p>体力劳动并没有什么错。</p><p>但你要明白，你是在用时间换钱。</p><p>而你的时间是有限的。</p><p>医生可以获得很高的薪水，但无论他们是救了某人的命，还是仅仅告诉他们吃点阿司匹林，他们拿到的钱是一样的。</p><p>一个作家的报酬可以随心所欲地上不封顶，这取决于他们写什么、他们的产品是什么，以及他们的作品传播得有多广。</p><p>写作只是这里的一个例子，因为我们将在本封信的后文讨论如何将你希望的任何事物变现。</p><p>创意工作者和体力劳动者之间的区别就在于是否拥有一家企业。</p><p>商业就是解决一系列创意问题，直到你创造出你渴望的收入和生活方式。</p><p>一旦你停止围绕产品和受众触达解决创意问题，你的收入就会停滞，你就会成为你自己亲手建立的工作的奴隶。</p><h3 id="我从靠时间到靠大脑的进化" tabindex="-1">我从靠时间到靠大脑的进化 <a class="header-anchor" href="#我从靠时间到靠大脑的进化" aria-label="Permalink to &quot;我从靠时间到靠大脑的进化&quot;">​</a></h3><p><img src="'+t+'" alt=""></p><p>当我刚开始做生意时，合乎逻辑的选择是凭借一项有价值的技能做自由职业者。</p><p>这似乎对新手很友好，而且启动成本为零。</p><p>经过多年的亲力亲为，随着责任的增加，建立这家企业所带来的喜悦慢慢消退了。</p><p>我只能接下特定数量的客户。</p><p>我每天的时间就那么多。</p><p>除非我想留在一个自己制造的朝九晚五里，否则我必须变得有创意。我必须进化。</p><p>创造力取决于你心智的扩展。</p><p>因此，通过学习和让自己接触未知事物，我发现了解决我问题的新机会。</p><p>我开始在网上写作以吸引新客户。</p><p>这消除了通过陌生邮件、陌生电话和陌生信息手动联系潜在客户这个吞噬时间的无底洞。</p><p>我打造了一款可以在我睡觉时自动销售的数字产品。</p><p>这消除了我生存上对客户工作的绝对依赖。</p><p>我把我的自由职业服务转型成了咨询服务。</p><p>这把我的客户工作时间砍掉了一半。我可以收费更高，做得更少，因为我是在帮助他们，而不是替他们代劳。</p><p>在这段时间里，我做出了一个改变我人生方向的发现：</p><p>如果我能获得一个读者，我就能获得一百万个。</p><p>如果我能获得一个买家，我就能获得一千个。</p><p>在拥有了280万读者和2万名买家之后，我的发现被证明是正确的。</p><p>现在，我的创造性问题解决能力已经进化超越了一人企业（one-person business）。</p><p>现在，我专注于打造 <a href="https://kortex.co/" target="_blank" rel="noreferrer">Kortex</a>，在不降低交付质量的前提下委派工作，并且不让自己过度劳累。</p><p>在我们开始之前的一个教训：</p><p>你无法将体力劳动彻底从你的生活中抹去。</p><p>这是一个缓慢而痛苦的进化过程，有时你还会倒退。</p><p>既然我已经承担起了创办一家更大公司的责任，我的大量基础劳动也随之大幅增加，但我相信凭借我之前的经验，我能迅速将其降下来。</p><h3 id="我们将讨论什么" tabindex="-1">我们将讨论什么： <a class="header-anchor" href="#我们将讨论什么" aria-label="Permalink to &quot;我们将讨论什么：&quot;">​</a></h3><ul><li>商业的常量营养素</li><li>技能的渐进式超负荷</li><li>注意力持续时间</li><li>如何重塑自我</li><li>在互联网上记录你的大脑</li><li>如何打造让你赚钱的品牌、内容、产品和促销活动</li></ul><p>在我们开始之前的另一件事——我们为 VIP 和 Mastermind（核心指导群）开放了更多名额。如果你是一位创始人、创作者（creator）、作家或营销人员，想要直接与我们合作打造你的社交媒体品牌、内容和产品……<a href="https://intake.kortex.co/" target="_blank" rel="noreferrer">请在这里申请</a>。</p><p>这封信很长，但绝对值得。</p><h2 id="健美与建立企业" tabindex="-1">健美与建立企业 <a class="header-anchor" href="#健美与建立企业" aria-label="Permalink to &quot;健美与建立企业&quot;">​</a></h2><p>当你解构身心时，你可以绘制出一些模式，从而加深你对生活大多数领域的理解。</p><p>我们将通过创办一家企业，把这些模式与财务领域联系起来。</p><p>正如我们在<a href="/letters/mental-aesthetics-how-to-build-a-beautiful-mind">《心智美学（Mental Aesthetics）》</a>中谈到的，我们可以把心智看作你的精神躯体。</p><p>我们也可以把你的企业看作是你对外展示的躯体或角色。</p><p>商业就是如此，它是一个价值交换的容器。</p><p><em>个人成长是自我发展，商业增长是他者发展。</em></p><p>在营养学中，有 4 种常量营养素：</p><ul><li>脂肪</li><li>碳水化合物</li><li>蛋白质</li><li>酒精</li></ul><p>在商业中，有 4 大支柱决定了你的成功：</p><ul><li>品牌</li><li>内容</li><li>产品</li><li>促销（推广）</li></ul><p>在营养学中，有大量的微量营养素维持着身体功能。</p><p>在商业中，你的技能、兴趣、经验、知识、创造力和个性，决定了你努力的效能。</p><p>你的工作就是用正确的创意营养来滋养你的企业以取得成功。</p><p>你也可以选择商业的生酮饮食法，把内容当作碳水化合物一样戒掉。</p><p>许多人走直接响应营销路线，只用广告来推动他们的业务，但内容的种种好处使得这种做法变得不够理智（特别是对于那些没有钱花在试错上来学习广告的初学者来说……<a href="/letters/my-story-the-untold-truth-of-dan-koe">我可是吃尽了苦头才学到这点的</a>）。</p><p>通过保持每天写内容的习惯：</p><ul><li>你可以验证高表现力的想法作为内容，用于你的广告或推广中。</li><li>你可以留住你获取的受众。你不必总是烧钱去获取新客户。</li><li>你可以通过为各个认知水平的人撰写内容，随着时间的推移创造出客户。</li></ul><p>你可以每年花几十万美元在广告上。</p><p>或者你可以花一年时间建立一个拥有 10 万粉丝的受众群，并获得相同数量的曝光度。</p><p>或者你两者都做，由你决定。</p><h3 id="技能与挑战的渐进式超负荷" tabindex="-1">技能与挑战的渐进式超负荷 <a class="header-anchor" href="#技能与挑战的渐进式超负荷" aria-label="Permalink to &quot;技能与挑战的渐进式超负荷&quot;">​</a></h3><p><img src="'+a+'" alt=""></p><p>刚起步时，作为一人企业（one-person business）承担太多是不明智的。</p><p>你必须成为营销、销售、运营和媒体部门。</p><p>为了创造品牌、内容、产品和推广，你至少需要学习以下基础知识：</p><ul><li>营销与销售</li><li>平面设计</li><li>网页设计</li><li>文案写作</li><li>内容写作</li><li>电子邮件营销</li><li>社交媒体</li></ul><p>这是福也是祸。</p><p>如果你从未学习过任何现代技能，这将需要一段时间。</p><p>一想到未来，而你又没有技能去创造清晰感，你就会感到不知所措和焦虑。</p><p>但社交媒体是边学边建的完美容器。</p><p>在健美运动中，你通过随着时间推移向杠铃上增加重量，来逐渐让肌肉超负荷。</p><p>如果你因为自负而举重，放了太多的重量，你举不起来，还会让自己看起来像个白痴。</p><p>从小处着手，随着时间积累你的技能栈。</p><p>除非你开始动手建立，否则不要开始学习。</p><p>购买课程、书籍，并在建设的过程中搜索教你如何做好这一切的内容。</p><p>创建一个项目。<br> 设定一个目标。<br> 学习一项技能。<br> 熟练掌握它，这样你就有精力进行下一个。<br> 重复。</p><p><strong>建立你的主页。</strong> 学习社交媒体和平面设计（为了你的横幅和头像）。</p><p><strong>开始撰写内容。</strong> 学习文案撰写、内容撰写、营销和帖子结构。</p><p><strong>构思一款产品。</strong> 学习营销、销售和报价创建。</p><p><strong>学习推广。</strong> 学习电子邮件营销、促销活动和文案撰写。</p><p>在做这一切的时候，不要沾沾自喜。</p><p>如果在最初的良好效果停止后你不去寻找更高的挑战，你就会感到无聊。</p><p>无聊会导致你想放弃，因为你觉得你可以把时间花在更好的事情上。</p><p>在健身房里，一个很好的做法是观察别人怎么做来纠正自己的姿势。你也可以在网上看别人的视频。</p><p>模仿其他创作者在这个领域里所做的事情。</p><p>从创作者的简介、内容和营销中汲取灵感。</p><p>但是——这是一个<em>巨大</em>的“但是”——要意识到比你更高级的人处于不同的层次。他们现在所做的，可能并不是他们刚起步时所做的。</p><p>这是一个漫长的实验过程。</p><h3 id="处于注意力下的时间" tabindex="-1">处于注意力下的时间 <a class="header-anchor" href="#处于注意力下的时间" aria-label="Permalink to &quot;处于注意力下的时间&quot;">​</a></h3><p><img src="'+i+'" alt=""></p><p>在力量训练中，有一个概念被称为<em>肌肉受张力时间</em>（time under tension）。</p><p>有人认为这是肌肉生长的主要驱动力（与渐进式超负荷相辅相成）。</p><p>我想在商业上也提出同样的论点，只不过是<em>处于<strong>注意力</strong>下的时间</em>。</p><p>这可以说是当你用写作和内容建立受众群体时，最需要关注的事情。</p><p>注意力是第三个千禧年的货币。</p><p>关注你的人越多，你的力量就越大。</p><p>作家、播客和 YouTuber 通常拥有最忠诚的受众。</p><p>为什么？因为信息塑造身份。</p><p>你留住的注意力越多，你传递的信息就越多。</p><p>你在对受众的心智进行编程，其方式有助于真正改变他们的生活。</p><p>你可以整天为社交媒体写短帖，但那些吸引了更多注意力的人总是会胜过你。</p><p>詹姆斯·克莱尔（James Clear）会获得更多的互动和覆盖面，因为：</p><ul><li>人们已经接受了他的世界观。</li><li>人们在自己的内容、新闻通讯和播客中引用他的话。</li><li>每当有其他人发布与克莱尔相关的观点时，权威性就会归于克莱尔，因为在阅读<em>你的</em>内容时，人们脑海中浮现的却是他。当他们阅读别人的内容时，克莱尔依然在占据着他们的注意力。</li></ul><p>这并不意味着像 X、Instagram 或 LinkedIn 这样的短内容没有用。恰恰相反。它们有自己的优势和用武之地。</p><p>在这里不要用非黑即白的方式思考。要全面地思考。</p><p>我把短格式平台视为一种更快吸引广大受众的方式，以为你的长格式平台（后者往往更难增长）提供燃料。</p><p>我几乎总是建议从短内容开始，以建立受众、建立人脉，并验证表现亮眼的想法，然后你就可以把它们变成长视频、新闻通讯，或者把它们全部合并成一本书。</p><p>而且，你做得越久，你留住的注意力就越多。在 1 到 6 个月后放弃是愚蠢的。</p><p>50 年的 1% 就是 6 个月。</p><p>如果这是你看到自己会做一辈子的工作，不要在新手教程阶段就退出。</p><p>如果我一年发布 365 篇帖子（在所有平台上），而这些帖子能留住 30 秒的注意力，那相当于一年内每个平台上，每位读者都被我留住了 3 个小时的注意力。</p><p>如果我每周创作 1 篇长内容（不管是给新闻通讯、YouTube 还是播客，内容都一样），而这些内容能留住 20 分钟的注意力，那就相当于每位读者在所有平台上被我留住了 52 个小时的注意力。</p><p>我会让你自己得出结论，想想我为什么要写一本可能会被数百万人购买的书。</p><p>所以，重要的是你要正确看待短内容平台的本质：</p><p>它们是一种更快建立广泛受众、验证想法、并将人们引导进入各种产品和长内容的方式。</p><p>对于写作者，我总是推荐使用 X 和一份电子报（newsletter）。</p><p>一开始，用一个短内容平台和一个长内容平台就够了。</p><p>然后，当你花了足够的时间真正看到增长之后，你就可以把你所有最好的短内容和长内容重新包装，用到不同的平台上。这正是我在<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">《2小时写作者》（2 Hour Writer）</a>中教的内容。</p><h2 id="把你自己变成一份事业-心智货币化" tabindex="-1">把你自己变成一份事业（心智货币化） <a class="header-anchor" href="#把你自己变成一份事业-心智货币化" aria-label="Permalink to &quot;把你自己变成一份事业（心智货币化）&quot;">​</a></h2><p><img src="'+r+'" alt=""></p><p>你的“自我”，或者说身份，就是你的心智之身。</p><p>“自我”是一张由概念、信念、想法、经历和感知交织而成的网，正是它让你能够在这个世界中导航前行。</p><p>从出生起你所学习和使用的信息，塑造了这个“自我”。</p><p>你的身份塑造了你的视角，而你的视角，是你能够理解并拓展的最重要的东西。</p><p>你的视角，就是你的现实。</p><p>一种视角，是由目标、问题，以及为达成目标而克服这些问题所需的技能所构成的一个框架。</p><p>它同时也由信念、知识和经历构成——这些要么限制、要么助力于目标的达成、问题的解决，以及知识的理解。</p><p>当我们没有意识到构成自身视角的那些目标或问题时，我们其实并没有在选择自己的行动。那些目标是被强加给我们的。</p><p>如果我们没有克服问题、达成目标所需的技能，我们就会变得焦虑、不堪重负，并消极到最终爆发的地步。</p><p>当你不去理解别人在生活、社交媒体、政治、宗教等方面的目标时——我们就很容易误读他们的处境，觉得他们做的事情很愚蠢。</p><p>实际上，是我们缺乏视角。</p><p>我们无法打开自己的心智，去看到我们并不是唯一的视角。</p><p>构成你视角的那些目标和问题，决定了你会把哪些信息感知为重要的。</p><p>随着时间推移，你所摄入的信息，要么强化你现在的样子，要么通过拓展你的视角——让它容纳更好的问题和更有意义的目标——来改变你。</p><p>从那些有意义的目标出发，你就能获得一套独特的技能组合来实现它们。</p><p><strong>A 有一个由社会强加给他的、并未被自己意识到的目标。</strong></p><p>他被灌输相信，成为一名医生是他人生唯一的道路。</p><p>所以，无论他自己是否意识到，他所接触到的一切信息、书籍、播客、社交媒体内容和对话，都会被他解读为有助于实现这个目标的信息。</p><p>他的技能组合，将在他试图达成这个目标的过程中，由这些信息塑造而成。</p><p>这里还有更多的目标和问题在影响着他的解读方式——比如他整天在手机上刷段子，因为他没有一个更强的目标要求他自我教育来实现它。</p><p><strong>B 有一个自己主动选择的、有意识的目标，这个目标是基于他意识到的一个问题而来的。</strong></p><p>这不仅让他更有可能实现目标，还让他在更多方面为成功做好了准备。</p><p>首先，这让他不至于成为社会矩阵（social matrix）的无意识产物——那个由政府、学校和父母代代相传、毫无根基的信息循环网络，他们这样做只是为了将同样的东西再教给他们的孩子。</p><p>其次，改变自己是谁、开创一条独特的人生道路、达成能解决迫切问题的目标——这条路，会为他铺出一条充满意义、金钱和精通的人生。</p><h3 id="把你的心智记录在互联网上-并为此获得报酬" tabindex="-1">把你的心智记录在互联网上（并为此获得报酬） <a class="header-anchor" href="#把你的心智记录在互联网上-并为此获得报酬" aria-label="Permalink to &quot;把你的心智记录在互联网上（并为此获得报酬）&quot;">​</a></h3><p>现在，我们已经对人类行为反馈循环有了一个非常简要的理解。</p><p>身份影响视角，视角影响对处境的感知，感知影响选择，选择又反过来影响身份，如此循环，无限往复。</p><p>要把你的心智变成一份事业，你的任务就是让自己的行为变得更好，从而去改变他人。</p><p><strong>1）品牌就是你在线上的人物形象或身份</strong></p><p>一份事业的前端就是品牌。这是他们在线上展示出来、用以吸引对的人、并展现自身数字身份的东西。</p><p>既然我们要把<em>你自己</em>变成这份事业，你的任务就是去吸引那些你最能帮到的人：</p><p>那些像你一样的人。</p><p>那些与你的过去或现在的自己拥有相同目标和问题、却还没有能力去实现和克服它们的人。</p><p>你已经拥有可以传授给那些比你落后一步的人的知识、经验和技能了。这就是你开启一份事业所需要的全部。</p><p>所以，你在网站、社交媒体主页，以及任何展示你品牌的地方，要做的事就是：</p><ul><li>暗示一个你能帮助人们实现的有意义的目标。</li><li>暗示一个你能帮助他们解决的迫切问题。</li><li>暗示你所教授的、能弥合问题与目标之间差距的兴趣或技能。</li></ul><p>这创造了你的数字现实。</p><p>它创造了你与你的客户所共享的那个框架，让你们能够交换知识与技能。</p><p>这不一定要在你的品牌宣传中明说出来。</p><p>它必须在你的设计、文字和视频中被暗示出来。</p><p>随着人们通过你的内容和产品对你有了更多了解，你的品牌会随着受关注时间的累积而逐渐形成。</p><p>我的品牌口号是：<em>少工作，多赚钱，享受生活。</em></p><p>我的个人简介有时是这样写的：<em>我写关于人类潜能、写作和心智掌控的内容，让你能做自己想做的事。</em></p><p>我不建议直接照搬这些，因为它们大概不适合你。我积累的受关注时间比你多，所以有自由不必说得那么明白。这需要你更深入地研究我的其他文章，比如<a href="/letters/value-creation-the-skill-that-built-my-one-person-business">《价值创造》</a>或者<a href="/letters/the-most-important-skill-of-the-21st-century-only-1-use-it">《21世纪最重要的技能》</a>。</p><p><strong>2）内容就是你的心态与技能</strong></p><p>当你意识到内容的力量时，它就成了一种必需品。</p><p>营销人员深知流量的力量、一份感兴趣客户名单的力量、以及长文写作或视频的力量——但他们中的许多人（包括我自己）都是很晚才涉足内容这个游戏的。</p><p>他们没有意识到，那场让你赚了数百万的长网络研讨会，其实完全可以变成一段在 YouTube 上获得几十万播放量的视频（一旦你掌握了社交媒体这个游戏的玩法）。</p><p>我理解网络研讨会的转化路径，或类似的方式，可能更具策略性，但这并不能排除写内容所带来的其他好处：</p><ul><li><strong>你会提升自己的思考能力。</strong> 你的想法会随着时间变得清晰，而这会波及到你生活的其他方面。如果你不先写出一个好想法，你就不可能拥有一个好点子。你最初的内容不会很好，这没关系。</li><li><strong>它大多数时候是免费的。</strong> 你可以自然增长，也可以把广告预算转移到付费增长上，通过与大玩家建立联系、让他们转发你的帖子（不要听任何告诉你这不管用的人，他们根本不懂。它对他们不管用，是因为他们的品牌、内容和策略都很烂）。</li><li><strong>你创造出客户。</strong> 与广告不同，你能留住自己的受众，随时可以对他们进行再营销。当你创作教育性内容时，人们会因为你的信息塑造了他们，而<em>变成</em>客户。</li><li><strong>你能快速验证和测试想法。</strong> 我可以发一条推文，如果它表现得比平时好，我就能把它变成一个销售页面的标题、YouTube 视频标题，或者一整个我知道会卖得出去的产品。</li></ul><p>以下是我如何帮助<a href="https://intake.kortex.co/" target="_blank" rel="noreferrer">与我合作的人</a>，通过剖析他们的心智来把它转化为内容、从而打造品牌的。</p><p>首先，回答以下这些问题（把答案写下来，这样你就能用这些答案来写内容）：</p><ol><li>有哪 5-10 条信念，在别人看来是“极端”或“疯狂”的，但对你来说却是很正常的？（这正是让你与众不同、并带来最大增长的东西。）例如：我相信创业适合每一个人，并且我能从心理学、机制、历史和哲学的角度给出支撑这一观点的理由。</li><li>有哪 5-10 项兴趣或技能，帮助你创造了你现在正过着的生活方式，并帮助你的粉丝去实现它？</li><li>这些兴趣或技能为什么重要？它们能帮助人们在生活中避免什么，或者获得什么？</li><li>关于这些技能或兴趣，人们需要了解哪些基础知识？（这能让你不至于讲得太高深、太上层，从而真正能与人产生共鸣。）</li></ol><p>现在，把这些和<a href="/letters/the-most-important-skill-of-the-21st-century-only-1-use-it">《参与度的10条科规则》</a>结合起来，试着把你列出的所有东西都转化成内容。理解上面我链接的《价值创造》中的原则，也会有所帮助。</p><p>在这个过程中，要写得让一个五年级学生也能读懂。</p><p>这是我在这个领域看到的一个巨大问题。人们用细分领域的行话把自己的信息搞得过于复杂，结果反而没能吸引人们对你所感兴趣的东西<em>产生</em>兴趣。</p><p>你要吸引的，不是那些已经感兴趣的人。你是要通过说服，<em>让</em>他们产生兴趣。</p><p>最后，这里有几个人们容易掉进去的陷阱：</p><p><em>陷阱一——他们把太多精力放在推广上，或者只顾着谈论自己的产品。</em></p><p>80%的时间里，谈论你的信念、观点，教育人们理解那些让他们在你所擅长的兴趣和技能上超越平均水平所必需的信息。少推广。这就像是在兑现你与受众之间积累的善意。</p><p><em>陷阱二——他们不理解结构与内容之间的重要区别。</em></p><p>这远远超出了为商业写内容的范畴。它是一个形而上学的原则。</p><p>眼下，先把你的<em>想法</em>套用到高绩效的结构和框架里，把它们当作辅助轮，直到你真正培养出自己的写作能力。去研究一下名言警句、电子报的结构、帖子的结构等等，试着把你的想法套进这些结构里。</p><p><em>陷阱三——他们不做研究，也不使用高绩效的切入角度。</em></p><p>任何想法都可能爆火。但只有当它以一种能吸引注意力的方式呈现出来——能娱乐人、教育人，或激励人——的时候才会如此。</p><p>你是一个多巴胺贩子。</p><p>你通过教给读者新东西、给出新的观点、娱乐他们，或者向他们展示他们在生活中还能做到更多，来提升他们大脑中的多巴胺水平。</p><p>研究一下你最喜欢的那些账号中最受欢迎的 X 帖子、Instagram 帖子和 YouTube 视频，开始训练你的大脑，让它学会用高绩效标题的方式去思考。</p><p>关于内容的启示：</p><p><em>好的内容，是当你在 6 到 12 个月的时间里，持续尝试把你的心态和技能注入到读者身上时才会产生的，而不是靠某一篇帖子。</em></p><p><strong>3）产品就是你如何达成一个有意义的目标</strong></p><p>当你自己就是那个细分领域时，人们关注你，是因为他们想要实现你所拥有的那种生活方式。他们想做你所做的事。</p><p>你已经在用你的内容教他们该怎么做了。</p><p>内容和产品之间的区别，在于便利性、清晰度，以及一个能带来结果的可复制系统。</p><p><em>你人生中达成过的、最有意义的目标是什么？</em></p><p>（我的例子：我靠写关于自己兴趣的内容谋生。）</p><p>（一个潜在的例子：我练出了六块腹肌，却没有做任何有氧运动。）</p><p>(另一个例子：我解锁了极度专注的能力，建立了自己的副业。)</p><p><em>人们需要采取哪些步骤才能达到那个目标？</em></p><p>(我的例子：写作、建立读者群、说服、销售。)</p><p>(潜在例子：极简主义训练和间歇性禁食。)</p><p><em>人们需要学习什么才能采取这些步骤？</em></p><p>(我的例子：社交媒体、文案、内容。)</p><p>(潜在例子：训练和营养原则。)</p><p><em>这些人每天可以练习和实践什么来达到目标？</em></p><p>(我的例子：2小时内容生态系统。)</p><p>(潜在例子：针对大忙人的高管训练系统。)</p><p>(我给这些系统起了花哨的名字，因为在营销中这被称为“独特机制”。它很新颖。新颖性能吸引注意力，让人们心想：“这也许就是最终解决我问题的办法！”)</p><p>砰，这就是你产品的大纲。</p><p>请注意，这些都是简短平庸的例子。你要更具体些。</p><p>你帮助人们实现的“有意义的目标”，取决于解决永恒市场中基于人性的一个迫切问题：健康、财富、人际关系和幸福。</p><p>如果你还没有以独特的方式实现一个有意义的目标，我将在另一封关于快速掌握新技能的信中帮助你。</p><p>在那之前：</p><ul><li>在你生活的一个领域设定一个目标。</li><li>让自己沉浸在与之相关的知识和教育中。</li><li>将这些知识记录为内容（教学是你学习并识别自己所不知的方式，从而能高效学习）。</li><li>关键点：尝试不同的技巧（比如训练计划、饮食、赚钱的方法等）。</li><li>找出不同技巧之间的基本原理、真相和法则。</li><li>通过创造你自己的路径来实现这个目标。</li></ul><p>然后，把它当作数字产品分发出去，让你在睡觉时也能卖钱，且利润率高得离谱。</p><p>从那时起，你就拥有了资源（读者群和收入），可以去建立你内心渴望的任何其他业务。</p><p><strong>4) 推广就是讲述你为何实现了目标</strong></p><p>人们不关心功能，他们关心的是好处。</p><p>假设每个人都是自私的，因为他们确实如此，哪怕这种自私源于因无私而自我感觉良好。</p><p>营销就是创造最有力量的“为什么”。</p><p>“为什么”暗示着一种转变。</p><p>转变才是人们想要的。</p><p>就像身材转变的历程在YouTube上总能获得大量观看。</p><p>或者像生活转变总能让你情绪激动，并在这个人身上投入感情。</p><p>转变就是一个故事，而这正是我们的大脑天生容易被吸引、信任并与之产生共鸣的东西。</p><p>所以，你需要做两件事中的一件：</p><ol><li>告诉人们为什么这个产品会改变他们的生活。</li><li>告诉人们为什么它改变了你的生活（因为他们在阅读时，会把它当作是在改变他们自己的生活）。</li></ol><p>我做营销人员已经快6年了。</p><p>以下是你想要真正赚点钱所需要知道的全部。</p><p>一个故事或转变由三部分组成：</p><ol><li>一个迫切的问题。</li><li>一个理想的结果。</li><li>一个清晰的解决方案。</li></ol><p>这就是你整个营销活动的全部。</p><p>你必须对每一项进行测试，直到你通过正确的定位挖到金矿，但之后你就能安稳一段时间了。</p><p>无论是在电子邮件、落地页、IG Story、YouTube推广还是其他地方，只要你要求别人购买你的产品，都会用到这3个组成部分。</p><p>长文推广就像一个完整的销售页面，你必须引导人们走过这个结构，以此来填满页面（去读读这封信的开头吧）。</p><p>短文推广就像电子邮件中的行动号召，比如：</p><p>如果你尝试过“最新、最棒”的商业模式却没有取得任何成功（并且正在考虑认命去打一份全职工作），那是因为你陷入了战术的陷阱。</p><p>在<a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">数字经济学（Digital Economics）</a>中，我教授如何建立一家有目标感的企业的各项原则。</p><p>品牌、内容、产品和推广，好让你能谈论自己的兴趣爱好，并赚取创作收入。</p><p>那么，在撰写推广文案时，你必须知道你在和受众中的哪一部分人对话。他们阅读你的内容有多久了，他们理解你的理念吗？</p><p>我经常看到这个错误。</p><p>人们使用着非常高级的词汇（比如“显化一种同频的生活，成为一个平静的存在”），而他们的受众对此根本毫不在乎。</p><p>如果你还没有向你的入门级受众定义什么是“同频”和“显化”，那就不要这样写。</p><p>要直截了当。要简单明了。要震撼人心。</p><p>给人们他们想要的。</p><p>不要给人们你认为他们想要的。</p><p>这篇就写到这里，已经太长了。</p><p>希望你喜欢。</p><p>Dan</p><hr><p><a href="/en/letters/make-millions-with-your-mind-turn-your-knowledge-into-a-business">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',259))])}const P=o(c,[["render",g]]);export{q as __pageData,P as default};
